const SIGMA=5.67e-8;
const DT=86400;
const CS=1.5e7;
const CA=1e7;
function getTau(params, state){
  if(params.rampLwOpticalDepth){
    const start=params.lwOpticalDepthStart ?? 0.5;
    const end=params.lwOpticalDepthEnd ?? 3;
    const duration=10000;
    const p=Math.min(state.stepCount/duration,1);
    return start + (end-start)*p;
  }
  if(params.lwOpticalDepth !== undefined) return params.lwOpticalDepth;
  if(state.current_tau !== undefined) return state.current_tau;
  return 1.5;
}
exports.init=(params,rng)=>{
  const solar=params.solarConstant ?? 1361;
  const albedo=params.albedo ?? 0.3;
  const sw_tau=params.swOpticalDepth ?? 0;
  const tau=getTau(params,{stepCount:0,current_tau:params.lwOpticalDepth ?? 1.5});
  const ASR_total=solar/4*(1-albedo);
  const Teff=Math.pow(ASR_total/SIGMA,0.25);
  const sw_trans=Math.exp(-sw_tau);
  const ASR_surface=ASR_total*sw_trans;
  const epsilon=1-Math.exp(-tau);
  const Ts=Teff;
  const Ta=Teff*0.95;
  const DLW=epsilon*SIGMA*Math.pow(Ta,4);
  const ULW=SIGMA*Math.pow(Ts,4);
  const OLR=(1-epsilon)*ULW + epsilon*SIGMA*Math.pow(Ta,4);
  const toa_net=ASR_total-OLR;
  return {Ts,Ta,stepCount:0,surface_down_sw:ASR_surface,downwelling_lw:DLW,outgoing_lw:OLR,toa_net_flux:toa_net,upwelling_lw:ULW,current_tau:tau};
};
exports.step=(state,params,rng)=>{
  const solar=params.solarConstant ?? 1361;
  const albedo=params.albedo ?? 0.3;
  const sw_tau=params.swOpticalDepth ?? 0;
  const tau=getTau(params,state);
  const epsilon=1-Math.exp(-tau);
  const ASR_total=solar/4*(1-albedo);
  const sw_trans=Math.exp(-sw_tau);
  const ASR_surface=ASR_total*sw_trans;
  const ASR_atm=ASR_total*(1-sw_trans);
  const Ts=state.Ts;
  const Ta=state.Ta;
  const DLW=epsilon*SIGMA*Math.pow(Ta,4);
  const ULW_surface=SIGMA*Math.pow(Ts,4);
  const OLR=(1-epsilon)*ULW_surface + epsilon*SIGMA*Math.pow(Ta,4);
  const net_surface=ASR_surface + DLW - ULW_surface;
  const net_atm=ASR_atm + epsilon*ULW_surface - 2*DLW;
  let Ts_new=Ts + net_surface*DT/CS;
  let Ta_new=Ta + net_atm*DT/CA;
  if(Ts_new<10) Ts_new=10;
  if(Ta_new<10) Ta_new=10;
  const DLW_new=epsilon*SIGMA*Math.pow(Ta_new,4);
  const ULW_new=SIGMA*Math.pow(Ts_new,4);
  const OLR_new=(1-epsilon)*ULW_new + epsilon*SIGMA*Math.pow(Ta_new,4);
  const toa_net_new=ASR_total-OLR_new;
  return {Ts:Ts_new,Ta:Ta_new,stepCount:state.stepCount+1,surface_down_sw:ASR_surface,downwelling_lw:DLW_new,outgoing_lw:OLR_new,toa_net_flux:toa_net_new,upwelling_lw:ULW_new,current_tau:tau};
};
exports.observe=(state,params)=>({
  surface_temp_K: state.Ts,
  downwelling_lw_Wm2: state.downwelling_lw,
  toa_net_flux_Wm2: state.toa_net_flux,
  surface_down_sw_Wm2: state.surface_down_sw
});
exports.view=(state,params)=>{
  const stages=["Sun","Atmosphere","Surface","Space"];
  const query=`Ground ${Math.round(state.Ts)}K`;
  const rows=[
    {id:"sun_down",stage:"Sun",label:"Sunlight down",flux:Math.round(state.surface_down_sw),color:"#ffcc33"},
    {id:"heat_up",stage:"Surface",label:"Heat up",flux:Math.round(state.upwelling_lw),color:"#ff5533"},
    {id:"heat_down",stage:"Atmosphere",label:"Heat back down",flux:Math.round(state.downwelling_lw),color:"#ff8866"},
    {id:"heat_out",stage:"Space",label:"Heat to space",flux:Math.round(state.outgoing_lw),color:"#66ccff"}
  ];
  return {kind:"pipeline",stages,query,rows,error:null};
};
